('pool-hydrator', 'Keep the CONDUIT pool at >=18 waiting tasks focused on the Cloudflare platform (Agents Week 2026 era): Workers, R2, D1, Queues, MCP governance, Code Mode, AI Gateway, Sandboxes, Email Service, and hardening the existing worker modules. Check depth: SELECT COUNT(*) FROM task_pool WHERE instance_target=''conduit'' AND status=''waiting''. If <18, generate 10 specific IMPLEMENTATION tasks (build/configure/harden, not research). Priority 10-50. Insert them, re-queue yourself with priority 1, and log a pool.hydrated event.', 'meta', 'conduit', 1, 8);

-- TASK POOL (12 tasks)
INSERT INTO task_pool (task_name, prompt, category, instance_target, priority, estimated_minutes) VALUES
('mcp-governance-stack', 'Build the Cloudflare MCP governance reference architecture: Cloudflare Access in front of MCP servers (auth), an MCP server portal for centralized governance, AI Gateway for cost controls/logging, and Cloudflare Gateway rules to detect Shadow MCP (unauthorized MCP servers). Wire at least Access + AI Gateway for one real MCP server. Document the layered model.', 'mcp', 'conduit', 10, 30),
('code-mode-adoption', 'Adopt Cloudflare Code Mode to cut MCP token overhead (~81% vs classic tool-schema loading). Identify tool-heavy MCP flows, collapse tool definitions into the Code Mode central-tools pattern so schemas aren''t loaded upfront. Convert one flow end-to-end and measure the token delta. Document the before/after.', 'mcp', 'conduit', 14, 25),
('ai-gateway-setup', 'Stand up Cloudflare AI Gateway as the single inference endpoint (70+ models, multiple providers, unified billing). Configure: caching, rate limiting, cost caps, request logging, and fallback ordering. Point at least one worker''s model calls through the gateway. Document the config and the cost controls.', 'ai', 'conduit', 16, 22),
('cf-email-service-beta', 'Evaluate and wire Cloudflare Email Service (public beta) to send/receive/process email natively from a worker. Compare against the existing email-handler module (which parses inbound MIME to R2). Prototype native send + inbound processing. Document how it augments or replaces the current email path. Keep DMARC/SPF/DKIM alignment intact (coordinate with FORTRESS).', 'email', 'conduit', 20, 25),
('sandboxes-execution', 'Use Cloudflare Sandboxes (GA) to run agent-generated code in isolation. Set up a sandbox, define resource limits, and route one untrusted-code path through it instead of executing inline. Document the isolation boundary and limits.', 'compute', 'conduit', 24, 22),
('r2-hardening', 'Harden R2 access. Add bearer-token auth on upload endpoints (secret via `wrangler secret put`, compared with crypto.subtle.timingSafeEqual to defeat timing attacks). Use pre-signed URLs for anonymous reads instead of public buckets. Put Cloudflare Access in front of sensitive buckets. Audit the r2-explorer worker for any unauthenticated write path (it ships readonly by default — keep it that way unless Access is configured). Document the model.', 'storage', 'conduit', 18, 25),
('d1-hardening', 'Harden D1 (the cannon database). Confirm all queries are parameterized (D1 already prevents SQLi via parameterized queries — verify no string interpolation exists in any worker touching D1). Front D1 with a proxy Worker + bearer auth for any external API access. Store the D1 API key as a secret. Document the access pattern. Encryption at rest (AES-256) + TLS in transit are automatic — note that.', 'database', 'conduit', 22, 22),
('workers-best-practices-pass', 'Run the Feb-2026 Cloudflare Workers Best Practices checklist against every worker in the repo. Verify: secrets via `wrangler secret put` (never in wrangler config/source), timingSafeEqual for all token/HMAC/secret comparisons, HMAC on service bindings for defense-in-depth, no import.meta.url local file loads (unsupported), proper error handling. Fix violations. Commit and push. Document the audit results.', 'security', 'conduit', 26, 25),
('harden-existing-modules', 'Security pass on the 8 existing worker modules (email-handler, webhook-receiver, discord-bot, admin-dashboard, image-optimizer, hud-system, hud-discord, index-enhanced). For each: verify auth on every mutating endpoint, signature verification where inbound (Discord Ed25519 already fixed — verify webhook-receiver validates provider signatures too, e.g. GitHub HMAC, Stripe signature, Slack signing secret), no secret leakage, no unauth admin access. Fix gaps. Commit and push.', 'security', 'conduit', 30, 30),
('wrangler-secrets-migration', 'Migrate every worker credential to `wrangler secret put`. Audit wrangler.json / wrangler.enhanced.json and all source for hardcoded keys/tokens/URLs-with-auth. Move them to secrets, reference via env at runtime. Confirm the workers still build. Coordinate the inventory with FORTRESS''s secrets task to avoid double work. Document the secret names each worker expects.', 'secrets', 'conduit', 28, 18),
('queues-dlq-pattern', 'Add a Cloudflare Queues + Dead Letter Queue pattern for async work (webhook fanout, email processing, cannon side-effects). Producer enqueues, consumer processes with retries, failures land in a DLQ for inspection. Wire one real path (e.g. webhook-receiver -> queue -> processor). Document the topology and retry/DLQ policy.', 'reliability', 'conduit', 34, 20),
('observability-baseline', 'Establish an observability baseline across workers: enable Workers observability/logging, structured logs, tail sampling config, and a minimal metrics view (requests, errors, p50/p99). Confirm `wrangler tail` works for each deployed worker. Document how to watch each worker in production.', 'observability', 'conduit', 36, 18);

